import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2016-SEP-14 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2016-SEP-14 :: Ceph Performance Weekly","date":"2017-01-11T00:00:00.000Z","updated":"2017-01-12T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","RocksDB","BlueStore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2016-SEP-14_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2016-SEP-14_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),n={name:"posts/2017/2016-SEP-14_-_-_Ceph_Performance_Weekly.md"};function l(i,o,a,p,g,_){return t(),r("div",null,[...o[0]||(o[0]=[s("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Sage, Ellen, Sam, Alan, Leo, Lucy, Ian, Marge, Aver等</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及问题讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、主要进展</strong></p><ol><li><strong>编码解码方案</strong>： Sage提交了一个新的编码解码方案，该方案基于Ellen和Sam的工作，初步评估显示其性能至少与之前方案相当，甚至可能更好。团队正在探讨如何将其集成到BlueStore中，并利用其优势。</li><li><strong>Zipkin追踪</strong>： 基于现有工作的Zipkin追踪工作取得了进展，主要通过优化OSD中的map搜索。</li><li><strong>Sharding性能提升</strong>： 上周合并的sharding extent map改进了小随机写入性能，比filestore快约20-25%。</li><li><strong>RocksDB空间使用增加</strong>： 随着随机写入，RocksDB空间使用量逐渐增加，需要关注是否存在内存泄漏或空间使用不当。</li><li><strong>Bitmap分配器性能问题</strong>： 之前性能下降的问题已基本排除，正在重新测试并分析性能数据。</li><li><strong>RocksDB分析工具</strong>： Ian提出开发一个简单的RocksDB分析工具，用于统计不同键空间的键数量和平均大小等数据。</li></ol><p><strong>二、讨论议题</strong></p><ol><li><strong>Sharding性能问题</strong>： 需要进一步调查Sharding性能在测试初期比后期好的原因，可能需要调整shard大小或优化相关代码。</li><li><strong>RocksDB空间使用问题</strong>： 需要分析RocksDB空间使用量增加的原因，并采取措施防止内存泄漏或空间使用不当。</li><li><strong>Bitmap分配器性能问题</strong>： 需要重新测试并分析性能数据，找出性能下降的原因，并进行优化。</li><li><strong>RocksDB分析工具</strong>： 开发一个简单的RocksDB分析工具，以便更好地了解内存使用情况。</li></ol><p><strong>三、行动计划</strong></p><ol><li>Sage继续优化编码解码方案，并探讨其集成到BlueStore中的方法。</li><li>团队继续测试和优化Sharding性能，并关注空间使用情况。</li><li>团队重新测试并分析Bitmap分配器性能数据，找出性能下降的原因，并进行优化。</li><li>Ian开发RocksDB分析工具，以便更好地了解内存使用情况。</li></ol><p><strong>四、其他事项</strong></p><ol><li>Marge将合并漏查修复分支。</li><li>Aver将对漏查修复分支进行测试。</li><li>团队将继续关注RGW性能问题，并在适当的时候进行评估。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议讨论了Ceph分布式存储项目的最新进展和问题，并制定了相应的行动计划。团队将继续努力优化项目性能，并确保项目的稳定性和可靠性。</p>",15)])])}const d=e(n,[["render",l]]);export{S as __pageData,d as default};
